from fnmatch import fnmatch

# Each level on the path from root to account: (name, [(effect, action pattern)])
path = [
    ("Root",     [("Allow", "*")]),                      # FullAWSAccess
    ("Prod OU",  [("Allow", "*"), ("Deny", "iam:CreateUser")]),
    ("Account",  [("Allow", "s3:*"), ("Allow", "iam:*")]),
]

def scp_allows(action):
    for level, stmts in path:
        if any(e == "Deny" and fnmatch(action, p) for e, p in stmts):
            return f"DENY (explicit deny at {level})"
        if not any(e == "Allow" and fnmatch(action, p) for e, p in stmts):
            return f"DENY (no allow at {level})"
    return "passes SCPs"

for action in ["s3:GetObject", "iam:CreateUser", "ec2:RunInstances"]:
    print(f"{action:18} {scp_allows(action)}")

