from collections import deque

# Edge: who can become whom, and why (a toy account, not real data)
edges = {
    "user/intern":      [("role/ci-reader", "sts:AssumeRole (trust policy)")],
    "role/ci-reader":   [("role/lambda-ops", "iam:PassRole + lambda:CreateFunction")],
    "role/lambda-ops":  [("role/deployer", "sts:AssumeRole (role chaining)")],
    "role/deployer":    [("ADMIN", "iam:AttachRolePolicy on itself")],
    "user/analyst":     [],
}

def path_to_admin(start):
    queue, seen = deque([(start, [])]), {start}
    while queue:
        node, steps = queue.popleft()
        if node == "ADMIN":
            return steps
        for nxt, how in edges.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, steps + [f"{nxt:16} via {how}"]))
    return None

for who in ["user/intern", "user/analyst"]:
    steps = path_to_admin(who)
    print(who, "can reach admin" if steps else "has no path to admin")
    for s in steps or []:
        print("  ", s)

# Your role trusts the vendor's account. The vendor assumes roles for many customers.
VENDOR = "999988887777"
trust_old = {"principal": VENDOR}                          # no external ID check
trust_new = {"principal": VENDOR, "external_id": "12345"}  # your ID at the vendor

def sts_assume_role(trust, caller_account, external_id):
    if caller_account != trust["principal"]:
        return "AccessDenied"
    if "external_id" in trust and external_id != trust["external_id"]:
        return "AccessDenied"
    return "credentials for YOUR account"

# The vendor's own records: customer, the role ARN they registered, their external ID
customers = {
    "you":     ("arn:aws:iam::111122223333:role/ExampleRole", "12345"),
    "mallory": ("arn:aws:iam::111122223333:role/ExampleRole", "67890"),  # your ARN!
}

for trust_name, trust in [("old trust", trust_old), ("new trust", trust_new)]:
    for who, (role_arn, ext_id) in customers.items():
        result = sts_assume_role(trust, VENDOR, ext_id)
        print(f"{trust_name}: job for {who:8} {result}")

